INSERT INTO questions (idx, dataset, example_id, prompt_id, source, subject, question_number, prompt, question, choice_a, choice_b, choice_c, choice_d, answer, gold_passage, gold_idx, generated, subtopic)
VALUES
('mbe_373', 'mbe', '373', '212', 'MBE-1978-83-part5', '', '25', '', 'Linda was fifteen years old, but she appeared and acted older. When asked, she always said she was twenty-two, and she carried false identification saying she was that old. She frequented taverns and drank heavily. One evening in a bar she became acquainted with Duke. He believed her when she told him her claimed age. They had several drinks and became inebriated. Later, they drove in Duke''s car to a secluded spot. After they had necked for a while, Duke propositioned Linda and she consented. Before Duke achieved penetration, Linda changed her mind, saying, "Stop! Don''t touch me! I don''t want to do it." When Duke did not desist, Linda started to cry and said, "I am only fifteen." Duke immediately jumped from the car and ran away. Duke was indicted for attempted rape, assault with intent to rape, contributing to the delinquency of a minor, and attempted statutory rape. The age of consent in the jurisdiction is sixteen. The attempted rape charge can only be sustained if', 'the jury acquits Duke on all other charges', 'the State can show that Duke thought Linda was over the age of consent', 'the jury finds that Linda was resisting force used by Duke to accomplish an act of intercourse', 'evidence of Duke''s flight is not admitted by the trial judge', 'C', 'Rape is generally defined as engaging in sexual intercourse or deviate sexual activity with another person by forcible compulsion.  Attempted rape is defined as purposely engaging in conduct which constitutes a substantial step toward accomplishing the rape. It is not necessary to prove an unlawful entry into an occupiable structure to establish rape or attempted rape. Once the intent to rape has been formed and substantial steps to accomplish it have been taken the offense of rape or attempted rape can be committed anywhere. Since each offense requires proof of elements not required by the other a defendant can be convicted and sentenced on both offenses.', 'mbe_298', 0, '25'),
('mbe_374', 'mbe', '374', '213', 'MBE-1978-83-part5', '', '26', 'Paul and Daniel entered a contract in writing on November 1, the essential part of which read as follows: "Paul to supply Daniel with 200 personalized Christmas cards on or before December 15, 1970, bearing photograph of Daniel and his family, and Daniel to pay $100 thirty days thereafter. Photograph to be taken by Paul at Daniel''s house. Cards guaranteed to be fully satisfactory and on time." Because Daniel suddenly became ill, Paul was unable to take the necessary photograph of Daniel and his family until the first week of December. The final week''s delay was caused by Paul''s not being notified promptly by Daniel of his recovery. Before taking the photograph of Daniel and his family, Paul advised Daniel that he was likely to be delayed a day or two beyond December 15 in making delivery because of the time required to process the photograph and cards. Daniel told Paul to take the photograph anyway. The cards were finally delivered by Paul to Daniel on December 17, Paul having diligently worked on them in the interim. Although the cards pleased the rest of the family, Daniel refused to accept them because, as he said squinting at one of the cards at arm''s length without bothering to put on his reading glasses, "The photograph makes me look too old. Besides, the cards weren''t delivered on time."', 'In an action by Paul against Daniel, which of the following would be Daniel''s best defense?', 'The cards, objectively viewed were not satisfactory.', 'The cards, subjectively viewed, were not satisfactory.', 'The cards were not delivered on time.', 'Daniel''s illness excused him from further obligation under the contract.', 'B', 'Where no time is fixed for the return of goods sold subject to the satisfaction of the buyer, they must be returned, or an offer made to return them, within a reasonable time; and a request for shipping directions and a statement that upon receiving them the goods will be returned is a sufficient offer to return.', 'mbe_299', 0, '26'),
('mbe_375', 'mbe', '375', '213', 'MBE-1978-83-part5', '', '27', 'Paul and Daniel entered a contract in writing on November 1, the essential part of which read as follows: "Paul to supply Daniel with 200 personalized Christmas cards on or before December 15, 1970, bearing photograph of Daniel and his family, and Daniel to pay $100 thirty days thereafter. Photograph to be taken by Paul at Daniel''s house. Cards guaranteed to be fully satisfactory and on time." Because Daniel suddenly became ill, Paul was unable to take the necessary photograph of Daniel and his family until the first week of December. The final week''s delay was caused by Paul''s not being notified promptly by Daniel of his recovery. Before taking the photograph of Daniel and his family, Paul advised Daniel that he was likely to be delayed a day or two beyond December 15 in making delivery because of the time required to process the photograph and cards. Daniel told Paul to take the photograph anyway. The cards were finally delivered by Paul to Daniel on December 17, Paul having diligently worked on them in the interim. Although the cards pleased the rest of the family, Daniel refused to accept them because, as he said squinting at one of the cards at arm''s length without bothering to put on his reading glasses, "The photograph makes me look too old. Besides, the cards weren''t delivered on time."', 'Which of the following statements is most accurate?', 'Payment by Daniel of the $100 was a condition precedent to Paul''s duty of performance.', 'The performances of Paul and Daniel under the contract were concurrently conditional.', 'Payment by Daniel of the $100 was a condition subsequent to Paul''s duty of performance.', 'Performance by Paul under the contract was a condition precedent to Daniel''s duty of payment of the $100.', 'D', 'A condition precedent is an act or event, other than a lapse of time, which, unless the condition is excused, must occur before a duty to perform a promise in the agreement arises” (Oppenheimer & Co., 86 N.Y.2d at 690, 636 N.Y.S.2d 734, 660 N.E.2d 415 [internal quotation marks omitted]). An express condition -- that is, one agreed to by the parties that must be literally performed (substantial compliance will not suffice) -- must be reflected in clear, express language (see id. at 691, 636 N.Y.S.2d 734, 660 N.E.2d 415); “[c]ourts are reluctant to interpret a contractual clause as a condition precedent in the absence of ... unmistakable conditional language” ( *86 VXI Lux Holdco S.A.R.L. v. SIC Holdings, LLC, 171 A.D.3d 189, 195, 98 N.Y.S.3d 1 [1st Dept. 2019]).', 'mbe_300', 0, '27'),
('mbe_376', 'mbe', '376', '213', 'MBE-1978-83-part5', '', '28', 'Paul and Daniel entered a contract in writing on November 1, the essential part of which read as follows: "Paul to supply Daniel with 200 personalized Christmas cards on or before December 15, 1970, bearing photograph of Daniel and his family, and Daniel to pay $100 thirty days thereafter. Photograph to be taken by Paul at Daniel''s house. Cards guaranteed to be fully satisfactory and on time." Because Daniel suddenly became ill, Paul was unable to take the necessary photograph of Daniel and his family until the first week of December. The final week''s delay was caused by Paul''s not being notified promptly by Daniel of his recovery. Before taking the photograph of Daniel and his family, Paul advised Daniel that he was likely to be delayed a day or two beyond December 15 in making delivery because of the time required to process the photograph and cards. Daniel told Paul to take the photograph anyway. The cards were finally delivered by Paul to Daniel on December 17, Paul having diligently worked on them in the interim. Although the cards pleased the rest of the family, Daniel refused to accept them because, as he said squinting at one of the cards at arm''s length without bothering to put on his reading glasses, "The photograph makes me look too old. Besides, the cards weren''t delivered on time."', 'Which of the following statements regarding the legal effect of Daniel''s illness is LEAST accurate?', 'Daniel''s illness and the related developments excused Paul from his obligation to deliver the cards on or before December 15.', 'Prompt notice by Daniel to Paul of Daniel''s recovery from illness was an implied condition of Paul''s duty under the circumstances.', 'Paul was under a duty of immediate performance of his promise to deliver the cards, as of December 15, by reason of the express language of the contract and despite the illness of Daniel and the related developments.', 'Daniel''s conduct after his illness constituted a waiver of the necessity of Paul''s performing on or before December 15.', 'C', '“A party''s obligation to perform under a contract is only excused when the other party''s breach of the contract is so substantial that it defeats the object of the parties in making the contract.” Frank Felix Associates, Ltd. v. Austin Drugs, Inc., 111 F.3d 284, 289 (2d Cir.1997). See also Medical Malpractice Ins. Assoc. v. Hirsch (In re Lavigne), 114 F.3d 379, 387 (2d Cir.1997).', 'mbe_301', 0, '28'),
('mbe_382', 'mbe', '382', '215', 'MBE-1978-83-part5', '', '34', '', 'The most generally accepted basis on which a court will hold that X has a legal duty to aid another is the recognition by X that there is immediate danger of serious harm to', 'another human being from a stranger''s wrongful conduct', 'his neighbor from a stranger''s wrongful conduct', 'his cousin from a stranger''s wrongful conduct', 'another human being from X''s own nonnegligent conduct', 'D', '“ ‘Duty is a legal conclusion about relationships between individuals, made after the fact.... The nature of the duty, and the specific persons to whom it is owed, are determined by the circumstances surrounding the conduct of the individual.’ ” Clohessy v. Bachelor, 237 Conn. 31, 45, 675 A.2d 852 (1996). Although one generally has no legal duty to aid another in peril, even when the aid can be provided without danger or inconvenience to the provider, there are four widely recognized situations in which the failure to act may constitute breach of a legal duty: (1) where one stands in a certain relationship to another; (2) where a statute imposes a duty to help another; (3) where one has assumed a contractual duty; and (4) where one voluntarily has assumed the care of another. 1 W. LaFave & A. Scott, supra, § 3.3(a)(1)–(4), pp. 284–87.14 The state argues that this case falls within both the first and fourth situations, or some combination thereof.', 'mbe_302', 0, '34'),
('mbe_383', 'mbe', '383', '216', 'MBE-1978-83-part5', '', '35', 'Questions 35-36 are based on the four case summaries below. For each question, select the case that would be most applicable as a precedent.', 'Jones, angry at a neighbor with whom he had quar. reled, for revenge surreptitiously removed a piece of stone statuary from the neighbor''s garden and concealed it in his garage. He intended to return it a day or two later, after giving the neighbor a chance to feel bad over its being stolen. Suspecting who was guilty, the neighbor had Jones arrested and charged with larceny.', 'Commonwealth v. Mason. Two sisters see a wealthy neighbor''s pedigreed dog on the street. They take the dog home, intending to conceal it until the owner offers a reward. Held, guilty of larceny.', 'Saferite v. State. Two young men saw a motor car on the street with the keys in the ignition lock. They drove the car to a neighboring town with the intention, they said, of visiting the wife of one of them. The car was wrecked on their way back. Conviction for larceny reversed.', 'People v. Noblett. Defendant, a tenant of a city apartment, advertised it for sublease. Will agreed to sublease for three months, and on March 12 paid Defendant $550, the total agreed rental. Will was to receive possession on March 20, but possession was never given him. Held, not guilty of common law larceny.', 'King v. Pear. From a stablekeeper, Defendant hired a horse to go to Sutton and back, saying he would be back at 8 p.m. He did not return. Invest. gation showed that Defendant had given a false address, and that he had sold the horse the same day. Conviction of larceny affirmed.', 'B', 'For purposes of 11 U.S.C. § 523(a)(4), “larceny” means the fraudulent and wrongful taking and carrying away of the property of another with intent to convert such property to the taker''s use without the consent of the owner. Sherali v. S & S Food Corp. (In re Sherali), 490 B.R. 104, 124 (Bankr. N.D. Tex. 2013)', 'mbe_303', 0, '35'),
('mbe_384', 'mbe', '384', '216', 'MBE-1978-83-part5', '', '36', 'Questions 35-36 are based on the four case summaries below. For each question, select the case that would be most applicable as a precedent.', 'Harris, a heroin addict, broke into a home and took several cameras and watches, which he promptly pawned to obtain cash with which to purchase a "fix." Harris was later charged with larceny of the cameras and watches.', 'Commonwealth v. Mason. Two sisters see a wealthy neighbor''s pedigreed dog on the street. They take the dog home, intending to conceal it until the owner offers a reward. Held, guilty of larceny.', 'Saferite v. State. Two young men saw a motor car on the street with the keys in the ignition lock. They drove the car to a neighboring town with the intention, they said, of visiting the wife of one of them. The car was wrecked on their way back. Conviction for larceny reversed.', 'People v. Noblett. Defendant, a tenant of a city apartment, advertised it for sublease. Will agreed to sublease for three months, and on March 12 paid Defendant $550, the total agreed rental. Will was to receive possession on March 20, but possession was never given him. Held, not guilty of common law larceny.', 'King v. Pear. From a stablekeeper, Defendant hired a horse to go to Sutton and back, saying he would be back at 8 p.m. He did not return. Invest. gation showed that Defendant had given a false address, and that he had sold the horse the same day. Conviction of larceny affirmed.', 'A', 'The general larceny crime is also divided into grand larceny and petit larceny depending upon the value of the property taken and whether it was taken from the person of another. 21 O.S.2011, § 1703 (larceny is divided into two degrees: grand larceny and petit larceny); 21 O.S.Supp.2016, § 1704 (grand larceny is larceny committed when the value of the property taken exceeds $1,000.00 or when such property, although not of value exceeding $1,000.00 is taken from the person of another; larceny in all other cases is petit larceny).
¶15 Title 21 O.S.2011, § 1717 further provides that “All animals of the dog kind, whether male or female, shall be considered the personal property of the owner thereof, for all purposes.” Title 21 O.S.2011, § 1718 states that: The taking of personal property of the kind defined in Section 1717 of this title, accomplished by fraud or stealth, and with the intent to deprive another thereof, is hereby defined as larceny and punishable in the same manner and to the same degree as in larceny of other descriptions of property. Id. (emphasis added). In other words, the theft of a dog may be prosecuted under the general larceny statute, i.e., Section 1701, as larceny of personal property.', 'mbe_304', 0, '36'),
('mbe_386', 'mbe', '386', '218', 'MBE-1978-83-part5', '', '38', '', 'Baker, the seller, authorized Ruiz in writing to sign a contract for the sale and purchase of land for her. Arthur, the buyer, orally authorized Thomas to sign the contract for him. Ruiz and Thomas signed the contract: "Baker by Ruiz, her agent" and "Arthur by Thomas, his agent." Arthur refuses to complete the purchase. Baker sues Arthur who pleads the Statute of Frauds. Baker will', 'win, because the sales contract was in writing', 'win, because her agency contract was in writing', 'lose, because she did not sign the contract personally', 'lose, because Arthur''s agency contract was not in writing', 'D', 'The undisputed facts in this case support the trial court''s conclusion.  As a general rule, a contract involving the sale of land or interests therein “must be in writing to be enforceable.” Chomicky v. Buttolph, 147 Vt. 128, 130, 513 A.2d 1174, 1175 (1986); 12 V.S.A. § 181(5). An exception to this rule exists where a party demonstrates that he or she is equitably entitled to the claimed interest in land. Gorton, 167 Vt. at 361–62, 706 A.2d at 950–51. In such cases, “[e]nforcement is justified on the ground that repudiation by one party after the other has fully performed amounts to a virtual fraud.” Id. at 361, 706 A.2d at 950; see also Contractor''s Crane Serv., Inc. v. Vt. Whey Abatement Auth., 147 Vt. 441, 449, 519 A.2d 1166, 1172 (1986) (“[I]f a party relies on an oral promise, fully performing its end of the bargain, then a written promise is not required if it would be fraud to allow the promisor to deny the contract.”).', 'mbe_305', 0, '38'),
('mbe_387', 'mbe', '387', '219', 'MBE-1978-83-part5', '', '39', '', 'A state statute requires that all buses which operate as common carriers on the highways of the state shall be equipped with seat belts for passengers. Transport Lines, an interstate carrier, challenges the validity of the statute and the right of the state to make the requirement. What is the best basis for a constitutional challenge by Transport Lines?', 'Violation of the due process clause of the Fourteenth Amendment', 'Violation of the equal protection clause of the Fourteenth Amendment', 'Unreasonable burden on interstate commerce', 'Difficulty of enforcement', 'C', 'When a state law does not discriminate against interstate commerce, but burdens it in some way, the law will violate the dormant Commerce Clause under a rational basis test only if the burden on interstate commerce is clearly excessive in relation to the putative local benefits. U.S. Const. art. 1, § 8, cl. 3.', 'mbe_306', 0, '39'),
('mbe_388', 'mbe', '388', '220', 'MBE-1978-83-part5', '', '40', '', 'Amy Docent, a state college instructor, was discharged because of her refusal to comply with a state statute requiring public employees to swear or affirm that they will (1) "uphold and defend" the state and federal constitutions and (2) "oppose the overthrow" of the state or federal governments "by force, violence, or by any improper method." The statute had previously been held constitutional by the state supreme court. Docent filed a complaint in federal district court alleging the unconstitutionality of the statute and seeking an injunction and damages. Which of the following is the state''s strongest argument for sustaining the validity of the statute?', 'Government employment is a privilege, not a right.', 'The oath as a whole is only a commitment to abide by constitutional processes.', 'The First and Fourteenth Amendments permit a state to fix the conditions of state employment.', 'The state has a compelling need to keep disloyal persons out of governmental positions of trust.', 'B', 'Instead, as the U.S. Supreme Court has clarified, “the First Amendment simply protects a public employee''s right, in certain circumstances, to speak as a citizen addressing matters of public concern.” For this reason, if a public employee is not speaking as a private citizen and/or is not speaking about a matter of public concern, their federal employer is free to restrict their speech without violating the First Amendment.', 'mbe_307', 0, '40'),
('mbe_391', 'mbe', '391', '222', 'MBE-1978-83-part5', '', '43', 'In 1945 Owen, owner of both Blackacre and Whiteacre, executed and delivered two separate deeds by which he conveyed the two tracts of land as follows: Blackacre was conveyed "To Alpha and his heirs as long as it is used exclusively for residential purposes, but if it is ever used for other than residential purposes, to the American Red Cross." Whiteacre was conveyed "To Beta and her heirs as long as it is used exclusively for residential purposes, but if it is used for other than residential purposes prior to 1965, then to the Salvation Army." In 1950 Owen died leaving a valid will by which he devised all his real estate to his brother, Bill. The will had no residuary clause. Owen was survived by Bill and by Owen''s daughter, Della, who was Owen''s sole heir. For the purpose of this set of questions, it may be assumed that the common law rule against perpetuities applies in the state where the land is located and that the state also has a statute providing that, "All future estates and interests are alienable, descendible, and devisable in the same manner as possessory estates and interests."', 'In 1955 Alpha and Della entered into a contract with John whereby Alpha and Della contracted to sell Blackacre to John in fee simple. After examining title, John refused to perform on the ground that Alpha and Della could not give good title. Alpha and Della joined in an action against John for specific performance. Prayer for specific performance will be', 'granted, because Alpha and Della together own a fee simple absolute in Blackacre', 'granted, because Alpha alone owns the entire fee simple in Blackacre', 'denied, because Bill has a valid interest in Blackacre', 'denied, because the American Red Cross has a valid interest in Blackacre', 'C', 'Specific performance is an equitable remedy, and the decision whether or not to order it is “confided to the ‘sound and informed discretion’ of the trial court.” “Specific performance of a contract is ordered when the legal remedy, usually money damages, is deemed to be either inadequate or impracticable. When land is the subject matter of the agreement, the legal remedy is assumed to be inadequate, since each parcel of land is unique....” Thus, it is routine for courts to enforce contracts to purchase real estate by ordering that they be specifically performed.', 'mbe_308', 0, '43'),
('mbe_392', 'mbe', '392', '222', 'MBE-1978-83-part5', '', '44', 'In 1945 Owen, owner of both Blackacre and Whiteacre, executed and delivered two separate deeds by which he conveyed the two tracts of land as follows: Blackacre was conveyed "To Alpha and his heirs as long as it is used exclusively for residential purposes, but if it is ever used for other than residential purposes, to the American Red Cross." Whiteacre was conveyed "To Beta and her heirs as long as it is used exclusively for residential purposes, but if it is used for other than residential purposes prior to 1965, then to the Salvation Army." In 1950 Owen died leaving a valid will by which he devised all his real estate to his brother, Bill. The will had no residuary clause. Owen was survived by Bill and by Owen''s daughter, Della, who was Owen''s sole heir. For the purpose of this set of questions, it may be assumed that the common law rule against perpetuities applies in the state where the land is located and that the state also has a statute providing that, "All future estates and interests are alienable, descendible, and devisable in the same manner as possessory estates and interests."', 'In 1946 the interest of the American Red Cross in Blackacre could be best described as a', 'valid contingent remainder', 'void executory interest', 'valid executory interest', 'void contingent remainder', 'B', 'The word “vest” in regards to the Rule refers to an immediate, fixed right of present or future enjoyment of the interest. Vest, BLACK''S LAW DICTIONARY (10th ed. 2014); see also Peveto, 645 S.W.2d at 772. The Rule does not apply to present or future interests that vest at their creation. Laddex, 513 S.W.3d at 480.  An executory interest is a future interest, held by a third person, that either cuts off another''s interest or begins after the natural termination of a preceding estate. Executory Interest, BLACK''S LAW DICTIONARY (10th ed. 2014). A springing executory interest is one that operates to end an interest left in the transferor. Springing Executory Interest, BLACK''S LAW DICTIONARY (10th ed. 2014); accord Peveto, 645 S.W.2d at 772. This interest does not vest at the execution of the deed, rather “executory interests vest an estate in the holder of the interest upon the happening of a condition or event.” 3 RICHARD R. POWELL, POWELL ON REAL PROPERTY § 20.05[2] (Michael Allan Wolf ed.). “Until such happening, they are non-vested future interests” and are subject to the Rule. Id. In contrast, a possibility of reverter is a future interest held by the grantor and is not subject to the Rule because it vests at the moment of creation. El Dorado Land Co., L.P. v. City of McKinney, 395 S.W.3d 798, 802–03 (Tex. 2013); see Luckel v. White, 819 S.W.2d 459, 464 (Tex. 1991). A possibility of reverter is “the grantor''s right to fee ownership in the real property reverting to him if the condition terminating the determinable fee occurs.” Luckel, 819 S.W.2d at 464. This interest is properly viewed as a “claim[ ] to property that the grantor never gave away.” El Dorado Land Co., L.P., 395 S.W.3d at 802–03 (citing 3 POWELL ON REAL PROPERTY § 20.02[1] ).T', 'mbe_309', 0, '44'),
('mbe_393', 'mbe', '393', '223', 'MBE-1978-83-part5', '', '45', 'Brill saved the life of Ace''s wife, Mary, who thereafter changed her will to leave Brill $1,000. However, upon Mary''s death she had no property except an undivided interest in real estate held in tenancy by the entirety of Ace. The property had been purchased by Ace from an inheritance. After Mary died, Ace signed and delivered to Brill the following instrument: "In consideration of Brill''s saving my wife''s life and his agreement to bring no claims against my estate based on her will, I hereby promise to pay Brill $1,000." Upon Ace''s death, Brill filed a claim for $1,000. Ace''s executor contested the claim on the ground that the instrument was not supported by sufficient consideration.', 'In most states, would Brill''s saving of Mary''s life be regarded as sufficient consideration for Ace''s promise?', 'Yes, because Ace was thereby morally obligated to Brill', 'Yes, because Ace was thereby materially benefited', 'No, because Ace had not asked Brill to save her', 'No, because the value of Brill''s act was too uncertain', 'C', 'Consideration is “some right, interest, profit or benefit or some forbearance, detriment, loss or responsibility given, suffered or undertaken by the other.” Homestyle Direct, LLC v. DHS, 354 Or. 253, 262, 311 P.3d 487 (2013); see also Restatement (Second) of Contracts § 71(2) (1981) (defining “consideration” as a performance or return promise “sought by the promisor in exchange for his promise” and “given by the promisee in exchange for that promise”). Consideration is “the basis for a bargain that two parties reach; it is what is sought by the promisor in exchange for a promise and given by the promisee in exchange for the promise.” State v. Villagomez, 362 Or. 390, 397, 412 P.3d 183 (2018).', 'mbe_177', 0, '45'),
('mbe_394', 'mbe', '394', '223', 'MBE-1978-83-part5', '', '46', 'Brill saved the life of Ace''s wife, Mary, who thereafter changed her will to leave Brill $1,000. However, upon Mary''s death she had no property except an undivided interest in real estate held in tenancy by the entirety of Ace. The property had been purchased by Ace from an inheritance. After Mary died, Ace signed and delivered to Brill the following instrument: "In consideration of Brill''s saving my wife''s life and his agreement to bring no claims against my estate based on her will, I hereby promise to pay Brill $1,000." Upon Ace''s death, Brill filed a claim for $1,000. Ace''s executor contested the claim on the ground that the instrument was not supported by sufficient consideration.', 'With respect to the recital that Brill had agreed not to file a claim against Ace''s estate, what additional fact would most strengthen Brill''s claim?', 'Brill''s agreement was made in a writing he signed.', 'Brill reasonably believed he had a valid claim when the instrument was siged.', 'Mary had contribute to accumulation of the real property.', 'Brill paid Ace $1 when he received the instrument.', 'B', 'Contracts often contain recitals: provisions that do not make binding promises but merely recite background information about factual context or the parties’ intentions. Maryland law recognizes the general principle that such recitals are not binding and, while they may aid the court in interpreting the contract''s operative terms, cannot displace or supplement operative terms that are clear. See Pulaski v. Riland, 199 Md. 426, 86 A.2d 907, 910 (1952); Cty. Comm''rs of Charles Cty. v. Panda-Brandywine, L.P., 663 F. Supp. 2d 424, 430 (D. Md. 2009), aff''d, 401 F. App''x 831 (4th Cir. 2010). While such recitals are often set forth at the beginning of the agreement in “whereas” clauses, that is not always the case. See, e.g., Aramony v. United Way of America, 254 F.3d 403, 406, 413 (2d Cir. 2001) (concluding section titled “Purpose of the Plan” in ERISA plan document consisted of nonbinding recitals).', 'mbe_310', 0, '46'),
('mbe_395', 'mbe', '395', '223', 'MBE-1978-83-part5', '', '47', 'Brill saved the life of Ace''s wife, Mary, who thereafter changed her will to leave Brill $1,000. However, upon Mary''s death she had no property except an undivided interest in real estate held in tenancy by the entirety of Ace. The property had been purchased by Ace from an inheritance. After Mary died, Ace signed and delivered to Brill the following instrument: "In consideration of Brill''s saving my wife''s life and his agreement to bring no claims against my estate based on her will, I hereby promise to pay Brill $1,000." Upon Ace''s death, Brill filed a claim for $1,000. Ace''s executor contested the claim on the ground that the instrument was not supported by sufficient consideration.', 'On which of the following theories would it be most likely that Brill could recover?', 'Ace and Brill have made a compromise.', 'Ace must give restitution for benefits it would be unjust to retain.', 'Ace is bound by promissory estoppel.', 'Ace executed a binding unilateral contract.', 'A', '“A compromise is valid if there is a meeting of the minds of the parties as to exactly what they intended when the compromise was reached.” Sileo v. Berger, 2011-0295, p. 8 (La.App. 4 Cir. 9/28/11), 74 So.3d 753, 758–59 (citing Elder v. Elder & Elder Enter., Ltd., 2006-0703, p. 3 (La.App. 4 Cir. 1/11/07), 948 So.2d 348, 350); Feingerts v. State Farm Mut. Auto. Ins. Co., 2012-1598, p. 11 (La.App. 4 Cir. 6/26/13), 117 So.3d 1294, 1301. “Compromises are favored in the law and the burden of proving the invalidity of such an agreement is on the party attacking it.” Sileo, 2011–0295 at p. 8, 74 So.3d at 759 (citing Elder, 2006–0703 at p. 3, 948 So.2d at 350).
Contracts are formed by the consent of the parties established through offer and acceptance. La. C.C. art. 1927. “It follows that an enforceable compromise agreement formed by offer and acceptance[ ] may not be revoked by either party. The ‘flip side’ of this principle is that an agreement that has not been formed by offer and acceptance is not enforceable and therefore can be revoked by either party.” Richardson v. O''Byrne, 2000-2202, p. 8 (La.App. 4 Cir. 10/16/02), 830 So.2d 1013, 1020.', 'mbe_311', 0, '47'),
('mbe_396', 'mbe', '396', '224', 'MBE-1978-83-part5', '', '48', '', 'Brown suffered from the delusion that he was a special agent of God. He frequently experienced hallucinations in the form of hearing divine commands. Brown believed God told him several times that the local Roman Catholic bishop was corrupting the diocese into heresy, and that the bishop should be "done away with." Brown, a devout Catholic, conceived of himself as a religious martyr. He knew that shooting bishops for heresy is against the criminal law. He nevertheless carefully planned how he might kill the bishop. One evening Brown shot the bishop, who was taken to the hospital where he died two weeks later. Brown told the police he assumed the institutions of society would support the ecclasiastical hierarchy, and he expected to be persecuted for his God-inspired actions. Psychiatrist Stevens examined Brown and found that Brown suffered from schizophrenic psychosis, that in the absence of this psychosis he would not have shot the bishop, and that because of the psychosis Brown found it extremely difficult to determine whether he should obey the specific command that he do away with the bishop or the general commandment "Thou shalt not kill." Brown was charged with murder. If Brown interposes an insanity defense and the jurisdiction in which he is tried has adopted only the M''Naghten test of insanity, then the strongest argument for the defense under that test is that', 'Brown did not know the nature of the act he was performing', 'Brown did not know that his act was morally wrong', 'Brown did not know the quality of the act he was performing', 'Brown''s acts were the product of a mental disease', 'B', '“A finding of insanity based upon OCGA § 16-3-3 requires proof that (1) the accused acted under a delusional compulsion; (2) the criminal act was connected with the delusion; and (3) the delusion related to a fact which, if true, would have justified the act.” Appling v. State, 222 Ga.App. 327, 329 (3), 474 S.E.2d 237 (1996) (citation omitted). Here, all three requirements were shown.', 'mbe_312', 0, '48'),
('mbe_397', 'mbe', '397', '225', 'MBE-1978-83-part5', '', '49', 'Walker, a pedestrian, started north across the street in a clearly marked north-south crosswalk with the green traffic light in her favor. Walker was in a hurry, and so before reaching the north curb of the street, she cut to her left diagonally across the street to the east-west crosswalk and started across it. Just after reaching the east-west crosswalk, the traffic light turned green in her favor. She proceeded about five steps farther across the street to the west in the crosswalk when she was struck by a car approaching from her right that she thought would stop, but did not. The car driven by Driver, 81 years of age, who failed to stop his car after seeing that the traffic light was red against him. Walker had a bone disease, resulting in very brittle bones, that is prevalent in only 0.02 percent of the population. As a result of the impact Walker suffered a broken leg and the destruction of her family heirloom, a Picasso original painting that she was taking to her bank for safe-keeping. The painting had been purchased by Walker''s grandmother for $750 but was valued at $500,000 at the time of the accident. Walker has filed suit against Driver. Driver''s attorney has alleged that Walker violated a state statute requiring that pedestrians stay in the crosswalks, and that if Walker had not violated the statute she would have had to walk 25 feet more to reach the impact point and therefore would not have been at a place where she could have been hit by Driver. Walker''s attorney ascertains that there is a statute as alleged by Driver, that his measurements are correct, that there is a state statute requiring observance of traffic lights, and that Driver''s license expired two years prior to the collision.', 'The violation of the crosswalk statute by Walker should not defeat her cause of action against Driver because', 'Driver violated the traffic light statute at a later point in time than Walker''s violation', 'pedestrians are entitled to assume that automobile drivers will obey the law', 'Walker was hit while in the crosswalk', 'the risks that the statute was designed to protect against probably did not include an earlier arrival at another point', 'D', 'A statute''s violation is deemed negligence per se if the claimed injury (a) was caused by the law''s violation, (b) was of the type intended to be prevented by the statute, and (c) the injured party was a member of the class meant to be protected by the statute. Lockhart, ¶ 6. The determinative issue of law in this appeal from a summary judgment is whether violation of § 154 constitutes a negligent breach of the standard of care.', 'mbe_313', 0, '49'),
('mbe_398', 'mbe', '398', '225', 'MBE-1978-83-part5', '', '50', 'Walker, a pedestrian, started north across the street in a clearly marked north-south crosswalk with the green traffic light in her favor. Walker was in a hurry, and so before reaching the north curb of the street, she cut to her left diagonally across the street to the east-west crosswalk and started across it. Just after reaching the east-west crosswalk, the traffic light turned green in her favor. She proceeded about five steps farther across the street to the west in the crosswalk when she was struck by a car approaching from her right that she thought would stop, but did not. The car driven by Driver, 81 years of age, who failed to stop his car after seeing that the traffic light was red against him. Walker had a bone disease, resulting in very brittle bones, that is prevalent in only 0.02 percent of the population. As a result of the impact Walker suffered a broken leg and the destruction of her family heirloom, a Picasso original painting that she was taking to her bank for safe-keeping. The painting had been purchased by Walker''s grandmother for $750 but was valued at $500,000 at the time of the accident. Walker has filed suit against Driver. Driver''s attorney has alleged that Walker violated a state statute requiring that pedestrians stay in the crosswalks, and that if Walker had not violated the statute she would have had to walk 25 feet more to reach the impact point and therefore would not have been at a place where she could have been hit by Driver. Walker''s attorney ascertains that there is a statute as alleged by Driver, that his measurements are correct, that there is a state statute requiring observance of traffic lights, and that Driver''s license expired two years prior to the collision.', 'The failure of Driver to have a valid driver''s license has which of the following effects?', 'It makes Driver liable to Walker because Driver is a trespasser on the highway.', 'It would not furnish a basis for liability.', 'It proves that Driver is an unfit driver in this instance.', 'It makes Driver absolutely liable for Walker''s injury.', 'B', 'Contributory negligence is defined as “conduct on the part of the plaintiff which falls below the standard to which he should conform for his own protection and which is the legally contributing cause, cooperating with the negligence of the defendant, in bringing about the plaintiff''s harm.” Guerra, 204 Kan. at 313, 461 P.2d 737. Over time, however, this court recognized distinctions between the two doctrines, with contributory negligence seen as arising from tort law, while assumption of risk arose from an implied contract. Guerra, 204 Kan. at 313, 461 P.2d 737.', 'mbe_314', 0, '50'),
('mbe_399', 'mbe', '399', '225', 'MBE-1978-83-part5', '', '51', 'Walker, a pedestrian, started north across the street in a clearly marked north-south crosswalk with the green traffic light in her favor. Walker was in a hurry, and so before reaching the north curb of the street, she cut to her left diagonally across the street to the east-west crosswalk and started across it. Just after reaching the east-west crosswalk, the traffic light turned green in her favor. She proceeded about five steps farther across the street to the west in the crosswalk when she was struck by a car approaching from her right that she thought would stop, but did not. The car driven by Driver, 81 years of age, who failed to stop his car after seeing that the traffic light was red against him. Walker had a bone disease, resulting in very brittle bones, that is prevalent in only 0.02 percent of the population. As a result of the impact Walker suffered a broken leg and the destruction of her family heirloom, a Picasso original painting that she was taking to her bank for safe-keeping. The painting had been purchased by Walker''s grandmother for $750 but was valued at $500,000 at the time of the accident. Walker has filed suit against Driver. Driver''s attorney has alleged that Walker violated a state statute requiring that pedestrians stay in the crosswalks, and that if Walker had not violated the statute she would have had to walk 25 feet more to reach the impact point and therefore would not have been at a place where she could have been hit by Driver. Walker''s attorney ascertains that there is a statute as alleged by Driver, that his measurements are correct, that there is a state statute requiring observance of traffic lights, and that Driver''s license expired two years prior to the collision.', 'If Walker establishes liability on the part of Driver for her physical injuries, should Walker''s recovery include damages for a broken leg?', 'No, since only 0.02 percent of the population have bones as brittle as Walker''s', 'No, unless a person of ordinary health would probably have suffered a broken leg from the impact', 'Yes, because Driver could foresee that there would be unforeseeable consequences of the impact', 'Yes, even though the extent of the injury was not a foreseeable consequence of the impact', 'D', 'the so-called “eggshell plaintiff” rule. Under this principle, the tortfeasor is responsible for the full extent of the plaintiff''s damages even if those injuries would not have occurred but for the plaintiff''s pre-existing physical condition, disease, or susceptibility to injury.', 'mbe_315', 0, '51'),
('mbe_400', 'mbe', '400', '225', 'MBE-1978-83-part5', '', '52', 'Walker, a pedestrian, started north across the street in a clearly marked north-south crosswalk with the green traffic light in her favor. Walker was in a hurry, and so before reaching the north curb of the street, she cut to her left diagonally across the street to the east-west crosswalk and started across it. Just after reaching the east-west crosswalk, the traffic light turned green in her favor. She proceeded about five steps farther across the street to the west in the crosswalk when she was struck by a car approaching from her right that she thought would stop, but did not. The car driven by Driver, 81 years of age, who failed to stop his car after seeing that the traffic light was red against him. Walker had a bone disease, resulting in very brittle bones, that is prevalent in only 0.02 percent of the population. As a result of the impact Walker suffered a broken leg and the destruction of her family heirloom, a Picasso original painting that she was taking to her bank for safe-keeping. The painting had been purchased by Walker''s grandmother for $750 but was valued at $500,000 at the time of the accident. Walker has filed suit against Driver. Driver''s attorney has alleged that Walker violated a state statute requiring that pedestrians stay in the crosswalks, and that if Walker had not violated the statute she would have had to walk 25 feet more to reach the impact point and therefore would not have been at a place where she could have been hit by Driver. Walker''s attorney ascertains that there is a statute as alleged by Driver, that his measurements are correct, that there is a state statute requiring observance of traffic lights, and that Driver''s license expired two years prior to the collision.', 'Walker''s violation of the crosswalk statute should not be considered by the jury because', 'there is no dispute in the evidence about factual cause', 'as a matter of law the violation of the statute results in liability for all resulting harm', 'as a matter of aw Driver''s conduct was an independent intervening cause', 'as a matter of law the injury to Walker was not the result of a risk the statute was designed to protect against', 'D', '“Under that doctrine [of negligence per se], the unexcused violation of a statute or ordinance constitutes negligence per se if the provision (1) ‘protect[s] the class of persons in which the plaintiff is included’ and (2) ‘protect[s] against the type of harm which has occurred as a result of the violation.’ ” Stachowski, 95 N.E.3d at 544 (quoting City of Fort Wayne v. Parrish, 32 N.E.3d 275, 277 (Ind. Ct. App. 2015)).', 'mbe_316', 0, '52'),
('mbe_401', 'mbe', '401', '226', 'MBE-1978-83-part6', '', '1', '', 'Paulsen was eating in a restaurant when he began to choke on a piece of food that had lodged in his throat. Dow, a physician who was sitting at a nearby table, did not wish to become involved and did not render any assistance, although prompt medical attention would have been effective in removing the obstruction from Paulsen''s throat. Because of the failure to obtain prompt medical attention, Paulsen suffered severe brain injury from lack of oxygen. If Paulsen asserts a claim against Dow for his injuries, will Paulsen prevail?', 'Yes, if the jurisdiction relieves physicians of malpractice liability for emergency first aid.', 'Yes, if a reasonably prudent person with Dow''s experience, training, and knowledge would have assisted Paulsen.', 'No, because Dow was not responsible for Paulsen''s condition.', 'No, unless Dow knew that Paulsen was substantially certain to sustain serious injury.', 'C', 'Generally, a bystander has no duty to provide affirmative aid to an injured person, even if the bystander has the ability to help.', 'mbe_317', 0, '1'),
('mbe_402', 'mbe', '402', '227', 'MBE-1978-83-part6', '', '2', 'The state of Champlain enacts the Young Adult Marriage Counseling Act, which provides that, before any persons less than 30 years of age may be issued a marriage license, they must receive at least five hours of marriage counseling from a state-licensed social worker. This counseling is designed to assure that applicants for marriage licenses know their legal rights and duties in relation to marriage and parenthood, understand the "true nature" of the marriage relationship, and understand the procedures for obtaining divorces.', 'Pine, aged 25, contemplates marrying Ross, aged 25. Both are residents of the state of Champlain. Pine has not yet proposed to Ross because he is offended by the counseling requirement. Pine sues in federal court seeking a declaratory judgment that the Young Adult Marriage Counseling Act is unconstitutional. Which of the following is the clearest ground for dismissal of this action by the court?', 'Pine and Ross are residents of the same state.', 'No substantial federal question is presented.', 'The suit presents a nonjusticiable political question.', 'The suit is unripe.', 'D', 'As used here, “ripeness” refers to “ ‘an aspect of the doctrine of justiciability, specifically, the requirement that there be an actual, as opposed to a hypothetical, injury to the individual invoking the judicial power.’ ” Beck v. City of Portland, 202 Or. App. 360, 366, 122 P.3d 131 (2005) (quoting Coast Range Conifers v. Board of Forestry, 192 Or. App. 126, 129, 83 P.3d 966 (2004), rev''d on other grounds, 339 Or. 136, 117 P.3d 990 (2005)). In U.S. West Communications v. City of Eugene, 336 Or. 181, 81 P.3d 702 (2003), the court concluded that ORS 28.020—which allows a person to seek a declaratory judgment if the person’s rights “are affected by a constitution, statute, municipal charter, ordinance, contract or franchise”—codifies a ripeness requirement for justiciability of a declaratory relief action. 336 Or. at 191, 81 P.3d 702; see also Beck, 202 Or. App. at 366, 122 P.3d 131 (describing U.S. West Communications as “appl[ying] the test for ripeness set out in [two prior cases] in which the court explicitly identified ripeness as a jurisdictional issue”). “[T]he legislature’s use of the present tense phrase ‘are affected’ implies [that] the controversy must involve a dispute based on present facts rather than on contingent or hypothetical events.” U.S. West Communications, 336 Or. at 191, 81 P.3d 702. Similarly, ORS 34.040 requires that “a substantial interest of a plaintiff has been injured” (emphasis added), thereby codifying a ripeness requirement for justiciability of a writ of review proceeding.', 'mbe_318', 0, '2'),
('mbe_403', 'mbe', '403', '227', 'MBE-1978-83-part6', '', '3', 'The state of Champlain enacts the Young Adult Marriage Counseling Act, which provides that, before any persons less than 30 years of age may be issued a marriage license, they must receive at least five hours of marriage counseling from a state-licensed social worker. This counseling is designed to assure that applicants for marriage licenses know their legal rights and duties in relation to marriage and parenthood, understand the "true nature" of the marriage relationship, and understand the procedures for obtaining divorces.', 'In a case in which the constitutionality of the Young Adult Marriage Counseling Act is in issue, the burden of persuasion will probably be on the', 'person challenging the law, because there is a strong presumption that elected state legisla. tors acted properly', 'person challenging the law, because the Tenth Amendment authorizes states to determine the conditions on which they issue marriage licenses', 'state, because there is a substantial impact on the right to marry, and that right is fundamental', 'state, because there is a substantial impact on the discrete and insular class of young adults', 'C', 'Two types of classifications cause the Court to depart from its usual rational basis scrutiny under the Equal Protection Clause: when group burdened by the classification is "suspect"  (e.g., a racial or  ethnic minority,  women,  aliens)  or when  the classification burdens  what the Court  determines to  be  a  "fundamental  right."  The Court  has  been reluctant  to  add to what  was  a relatively short  list of fundamental rights  recognized beginning in the 1960s, and specifically rejected the suggestions, for example, that welfare payments or education be labeled the sort of fundamental rights that trigger heightened scrutiny.  Heightened scutiny has been limited to cases involving substantial burdens placed on the right to vote, the right to be a candidate (access to the ballot), the right to migrate to another state, the right to marry and procreate and live as a family unit, and to fees that prevent indigents from obtaining equal access to justice  (e.g, divorcing, maintaining parental rights, and obtaining transcripts and securing legal assistance for a criminal appeal).', 'mbe_319', 0, '3'),
('mbe_411', 'mbe', '411', '234', 'MBE-1978-83-part6', '', '11', 'Parents purchased a new mobile home from Seller. The mobile home was manufactured by Mobilco and had a ventilating system designed by Mobilco with both a heating unit and an air conditioner. Mobilco installed a furnace manufactured by Heatco and an air conditioning unit manufactured by Coolco. Each was controlled by an independent thermostat installed by Mobilco. Because of the manner in which Mobilco designed the ventilating system, the first time the ventilating system was operated by Parents, cold air was vented into Parents'' bedroom to keep the temperature at 68F (20''C). The cold air then activated the heater thermostat, and hot air was pumped into the bedroom of Child, the six-month-old child of Parents. The temperature in Child''s room reached more than 170F (77''C) before Child''s mother became aware of the condition and shut the system off manually. As a result, Child suffered permanent physical injury. Claims have been asserted by Child, through a duly appointed guardian, against Mobilco, Seller, Heatco, and Coolco.', 'If Child''s claim against Seller is based on negligence, the minimum proof necessary to establish Seller''s liability is that the ventilating system', 'was defective', 'was defective and had not been inspected by Seller', 'was defective and had been inspected by Seller, and the defect was not discovered', 'was defective, and the defect would have been discovered if Seller had exercised reasonable care in inspecting the system', 'D', 'Additionally, “[a] manufacturer may be held strictly liable for placing a defective product on the market if the plaintiff''s injury results from a reasonably foreseeable use of the product.” Saller v. Crown Cork & Seal Co., Inc., 187 Cal.App.4th 1220, 1231, 115 Cal.Rptr.3d 151 (2010). Each theory requires that a plaintiff plead and prove causation and damages. See County of Santa Clara v. Atlantic Richfield Co., 137 Cal.App.4th 292, 318, 40 Cal.Rptr.3d 313 (2006).', 'mbe_320', 0, '11'),
('mbe_412', 'mbe', '412', '234', 'MBE-1978-83-part6', '', '12', 'Parents purchased a new mobile home from Seller. The mobile home was manufactured by Mobilco and had a ventilating system designed by Mobilco with both a heating unit and an air conditioner. Mobilco installed a furnace manufactured by Heatco and an air conditioning unit manufactured by Coolco. Each was controlled by an independent thermostat installed by Mobilco. Because of the manner in which Mobilco designed the ventilating system, the first time the ventilating system was operated by Parents, cold air was vented into Parents'' bedroom to keep the temperature at 68F (20''C). The cold air then activated the heater thermostat, and hot air was pumped into the bedroom of Child, the six-month-old child of Parents. The temperature in Child''s room reached more than 170F (77''C) before Child''s mother became aware of the condition and shut the system off manually. As a result, Child suffered permanent physical injury. Claims have been asserted by Child, through a duly appointed guardian, against Mobilco, Seller, Heatco, and Coolco.', 'If Child''s claims against Mobilco, Heatco, and Coolco are based on strict liability in tort, Child will probably recover against', 'Mobilco only, because the ventilating system was defectively designed by Mobilco', 'Heatco only, because it was the excessive heat from the furnace that caused Child''s injuries', 'Mobilco and Heatco only, because the combination of Mobilco''s design and Heatco''s furnace caused Child''s injuries', 'Mobilco, Heatco, and Coolco, because the combination of Mobilco''s design, Heatco''s furnace, and Coolco''s air conditioning unit caused Child''s injuries', 'A', 'a manufacturer is strictly liable if its product is defectively manufactured, defectively designed, or distributed without adequate instructions or warnings.', 'mbe_321', 0, '12')
ON CONFLICT (idx) DO NOTHING;
